WITH unpacked AS (SELECT id, service, log_ts, level, status_code, context, COALESCE(context['version'], 'unknown') AS version_or_default, ARRAY_CONTAINS(MAP_KEYS(context), 'version') AS has_version, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs) SELECT id, service, log_ts, version_or_default, has_version, SUM(status_code) OVER w_recent AS last4_sum_status_code, MIN(status_code) OVER w_recent AS last4_min_status_code, MAX(status_code) OVER w_recent AS last4_max_status_code FROM unpacked WHERE service IN ('billing', 'auth', 'checkout') WINDOW w_recent AS (PARTITION BY service ORDER BY log_ts, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW);
